const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const {engine}=require('../pace_v0672.cjs');
const {random,state,hash}=require('../balance-matrix-v0697/run.cjs');
const file=name=>__dirname+'/'+name,models={baseline:'work/enemy-mobility-board-v06113/source.html',candidate:'work/enemy-mobility-board-v06113/candidate.html'};
const seed=(batch,scenario,replicate,side)=>crypto.createHash('sha256').update(`yiwu-king-advance-20261111:${batch}:${scenario}:${replicate}:${side}`).digest().readUInt32LE(0);
const prior=()=>JSON.parse(fs.readFileSync('github-release/docs/data/combat-line-0.6.99.json')).reports[0].runs.filter(r=>r.input.models.red==='candidate'&&r.winner!=='draw'&&Object.values(r.pieceActivity).filter(p=>p.side===r.winner&&p.damage>0).length===1);
function play(input){
  const {E,C}=engine(models.baseline),candidate=Object.values(input.models).includes('candidate')?engine(models.candidate).C:null;
  const controller=side=>input.models[side]==='candidate'?candidate:C;
  const s=state(E,input);
  if(input.relocate){
    const leader=E.get(s,input.leader);for(const id of Array.from(leader.learned))E.learn(s,leader.id,id);
    const guard=E.get(s,input.guard);for(const id of Object.keys(E.CARDS).filter(id=>E.CARDS[id].kind==='guard').slice(0,2))E.learn(s,guard.id,id);
    assert.equal(s.budget.red,0);assert.equal(s.budget.black,0);assert.equal(leader.learned.length,0);assert.equal(guard.learned.length,2);
  }
  const bSide=E.OTHER[input.aSide],rng={[input.aSide]:random(input.seedA),[bSide]:random(input.seedB)};
  const commands=[['create',s.scenario],...Array.from(s.pieces,p=>Array.from(p.learned,id=>['learn',p.id,id])).flat(),['start']];
  const pieceActivity=Object.fromEntries(Array.from(s.pieces,p=>[p.id,{side:p.side,kind:p.kind,cards:Array.from(p.learned),moves:0,rests:0,attacks:0,defenses:0,damage:0,captures:0,cardUses:0}])),initialHP=s.pieces.length*18;
  E.start(s);
  const stats={moves:0,rests:0,passes:0,battles:0,rounds:0,retreats:0,reversals:0},lastMoves=new Map();let steps=0;
  while(s.phase!=='ended'&&s.ply<2000&&steps++<14000){
    if(s.phase==='board'){
      let action=controller(s.turn).board(s,rng[s.turn],'standard');
      if(input.force&&s.ply+1===input.force.ply){assert.deepEqual(JSON.parse(JSON.stringify(action)),input.force.expected);action=input.force.action;}
      if(action.type==='pass'){E.pass(s);commands.push(['pass']);stats.passes++;}
      else if(action.type==='rest'){E.rest(s,action.id,action.card);commands.push(['rest',action.id,action.card]);stats.rests++;pieceActivity[action.id].rests++;}
      else{
        const p=E.get(s,action.id),target=E.at(s,action.x,action.y),old=[p.x,p.y],last=lastMoves.get(p.id);
        if(target){stats.battles++;lastMoves.delete(p.id);pieceActivity[p.id].attacks++;pieceActivity[target.id].defenses++;}
        else{stats.moves++;pieceActivity[p.id].moves++;if(last&&last[0]===action.x&&last[1]===action.y)stats.reversals++;lastMoves.set(p.id,old);}
        E.move(s,p.id,action.x,action.y);commands.push(['move',p.id,action.x,action.y]);
      }
    }else{
      assert.equal(s.phase,'duel');const a=E.get(s,s.duel.a),d=E.get(s,s.duel.d),aId=controller(a.side).combat(s,a.side,rng[a.side],'standard');
      if(aId==='retreat'){E.retreat(s);commands.push(['retreat']);stats.retreats++;}
      else{
        const dId=controller(d.side).combat(s,d.side,rng[d.side],'standard'),hpA=a.hp,hpD=d.hp;
        E.resolve(s,aId,dId);commands.push(['resolve',aId,dId]);stats.rounds++;
        pieceActivity[a.id].damage+=hpD-(E.get(s,d.id)?.hp||0);pieceActivity[d.id].damage+=hpA-(E.get(s,a.id)?.hp||0);
        if(!E.get(s,d.id))pieceActivity[a.id].captures++;if(!E.get(s,a.id))pieceActivity[d.id].captures++;
        if(E.CARDS[aId])pieceActivity[a.id].cardUses++;if(E.CARDS[dId])pieceActivity[d.id].cardUses++;
      }
    }
  }
  assert.equal(s.phase,'ended','对局未自然结束，不能记为和局');assert.equal(stats.moves+stats.rests+stats.passes+stats.battles,s.ply);
  assert.equal(Object.values(pieceActivity).reduce((n,p)=>n+p.damage,0),initialHP-s.pieces.reduce((n,p)=>n+p.hp,0));
  return {input,winner:s.winner,reason:s.reason,plies:s.ply,...stats,pieceActivity,commands,terminalSHA256:hash(JSON.stringify(s))};
}
module.exports={play,models,hash};

