const fs = require('node:fs'), assert = require('node:assert/strict');
const {play, models, hash} = require('../king-counter-v06113/driver.cjs');
const referenceFile = 'github-release/docs/data/balance-0.6.113.json';
const bytes = fs.readFileSync(referenceFile), reference = JSON.parse(bytes);
const audit = reference.longGameAudit.runs.find(r => r.input.scenario === 'full');
const prior = reference.reports.find(r => r.scenario === 'full').runs.find(r => r.terminalSHA256 === audit.terminalSHA256);
assert(prior && prior.plies === 622);
models.baseline = 'work/balance-matrix-v06113/source.html';
assert.equal(hash(fs.readFileSync(models.baseline)), reference.sourceSHA256);
assert.equal(hash(fs.readFileSync('github-release/index.html')), reference.sourceSHA256);
const inputs = [{...prior.input, models: {red: 'baseline', black: 'baseline'}}];
for (const row of audit.rows) for (const action of row.attacks) {
  if (row.battle || !action.finishes.length || action.captureLosesKing) continue;
  inputs.push({...prior.input, models: {red: 'baseline', black: 'baseline'}, force: {ply: row.ply, expected: row.actual, action: {type: 'move', id: action.id, x: action.x, y: action.y}}, expectedIndex: row.index});
}
assert.equal(inputs.length, 9);
const output = __dirname + '/runs.json';
const report = {sourceSHA256: reference.sourceSHA256, sourceCommit: reference.sourceCommit, reference: referenceFile, referenceSHA256: hash(bytes), driverSHA256: hash(fs.readFileSync(require.resolve('../king-counter-v06113/driver.cjs'))), runnerSHA256: hash(fs.readFileSync(__filename)), scope: '622步标准长局全部八个被放弃的首轮可靠吃子选择，各只替换一次；原查询照常消耗随机数，后续使用原版电脑。同根诊断，不计新随机样本。', inputs, runs: [], errors: [], completed: false};
fs.writeFileSync(output, JSON.stringify(report) + '\n', {flag: 'wx'});
for (const input of inputs) {
  try {
    const run = play(input);
    if (!input.force) {assert.deepEqual(run.commands, prior.commands); assert.equal(run.terminalSHA256, prior.terminalSHA256);}
    else {
      let index = 0;
      while (index < Math.min(run.commands.length, prior.commands.length) && JSON.stringify(run.commands[index]) === JSON.stringify(prior.commands[index])) index++;
      assert.equal(index, input.expectedIndex);
      assert.deepEqual(run.commands.slice(0, index), prior.commands.slice(0, index));
      assert.deepEqual(run.commands[index], ['move', input.force.action.id, input.force.action.x, input.force.action.y]);
      run.firstDifferenceCommandIndex = index;
    }
    report.runs.push(run);
    fs.writeFileSync(output, JSON.stringify(report) + '\n');
    console.log(JSON.stringify({completed: report.runs.length, total: inputs.length, force: input.force, plies: run.plies, winner: run.winner, reason: run.reason}));
  } catch (error) {
    report.errors.push({input, message: error.message}); fs.writeFileSync(output, JSON.stringify(report) + '\n'); throw error;
  }
}
report.completed = true; fs.writeFileSync(output, JSON.stringify(report) + '\n');
